SELECT 'gongkao', '偷换概念', 'kp-xingce-language-reading-detail-concept-swap', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "偷换概念（细节题死穴）"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心陷阱：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "选项把文段中的 A 偷偷换成了长得很像的 B。或者把“可能”换成了“必然”。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、高频偷换类型"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "偷换时态：“将要”发生的事，选项写成“已经”发生。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "偷换范围：“部分”人，选项写成“所有”人。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "偷换逻辑：“因为A所以B”，选项写成“只有A才B”。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "偷换主体：主语客体对调。"}]}]}]}]}$$ AS jsonb), NULL, '偷换概念的核心考点与解题技巧。', category_node.id, CAST('["言语理解", "片段阅读", "偷换概念"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_xingce_language_reading_detail_concept_swap", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
